#!/usr/bin/env python3
"""Rebuild self-contained runtime findings; no live browser or network request."""
import hashlib,json,re,subprocess,sys
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parent
def read(path):return json.loads(Path(path).read_text())
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def main():
 result=subprocess.run([sys.executable,'-m','unittest','discover','-s',str(ROOT),'-p','test_runtime_diagnostics.py','-v'],capture_output=True,text=True)
 (ROOT/'test-results.txt').write_text(result.stdout+result.stderr)
 if result.returncode:raise RuntimeError('Offline policy regression failed')
 count=int(re.search(r'Ran (\d+) tests',result.stderr).group(1));executed=sha(ROOT/'executed-runtime_diagnostics-v1.py');probes={}
 for f in sorted((ROOT/'probes').glob('*/receipt.json')):
  r=read(f);assert r['script_sha256']==executed,'Executed probe source hash mismatch';assert r['cookies_before_count']==0 and not r['cookie_values_or_storage_exported']
  assert sha(f.parent/r['raw_path'])==r['raw_sha256'],'Raw live evidence hash mismatch'
  if r.get('screenshot_path'):assert (f.parent/r['screenshot_path']).exists()
  probes[f.parent.name]={'receipt':str(f.relative_to(ROOT)),'receipt_sha256':sha(f),'http_status':r.get('http_status'),'result':r['result'],'engine':r['engine'],'headed':r['headed'],'python':r['runtime']['python'],'playwright':r['runtime']['packages']['playwright']['version'],'browser':r['browser_version'],'title':r.get('title'),'exact_error':r.get('exact_error'),'cookies_before':r['cookies_before_count'],'cookies_after':r['cookies_after_count'],'expected_selector_found':r.get('expected_selector_found'),'response_headers_allowlist':r['response_headers_allowlist'],'metadata_redaction':r.get('metadata_redaction')}
 assert len(probes)==3 and probes['gridics-chromium148-headless']['http_status']==200 and probes['gridics-chrome155-headless']['http_status']==200 and probes['flagstaff-chromium148-headed']['http_status']==403
 prior={f.stem:{'summary_path':str(f.relative_to(ROOT)),'summary_sha256':sha(f),'source_receipt_path':read(f)['source_receipt_path'],'source_receipt_sha256':read(f)['source_receipt_sha256']} for f in sorted((ROOT/'prior-evidence').glob('*.json'))}
 report={'generated_at':datetime.now(timezone.utc).isoformat(),'status':'bounded_runtime_diagnostics_complete_no_bypass','scope':'Three distinct ordinary browser experiments plus read-only prior-receipt/environment comparisons. No ecode360.com or municipal-code requests were sent by this diagnostic work. No sealed package changed.','tests':{'passed':count,'failed':0,'command':'python build_findings.py','log':'test-results.txt','python':sys.version.split()[0]},'source':{'current_script':'runtime_diagnostics.py','current_script_sha256':sha(ROOT/'runtime_diagnostics.py'),'executed_live_revision':'executed-runtime_diagnostics-v1.py','executed_live_revision_sha256':executed,'current_vs_executed_difference':'Final script redacts metadata URL query values. Browser launch/navigation/readiness/stop behavior unchanged; current offline tests cover redaction and stop policy. No additional live requests were made for that metadata adjustment.'},'live_experiments':probes,'exact_execution_commands':'experiment-commands.json','environment_inventory':['environment-python39.json','environment-python312.json'],'environment_findings':{'older_environment':'Python3.9.6 LibreSSL2.8.3 Playwright1.60.0; bundledChromium148 and installedChrome155 both actually reached Gridics200','current_review_environment':'Python3.12.14 OpenSSL3.5.8 Playwright1.64.0; package metadata requiresPython>=3.10. Prior CivicPlus receipt showsChrome155/Playwright1.64 public200; no new live test repeated here.','proxy_ca_presence':'No environment-discovered proxy or enabled scutil proxy flags and no custom CA override variables detected in either inspected environment; no environment TLS validation disable flag. No proxy URLs/credentials/CA paths recorded. This does not exclude transparent network policy or uninspected browser enterprise policy.','tls_scope':'The browser probes completed HTTPS and received HTTP responses; no TLS or launch error was observed in these three experiments. Python ssl backend differences do not by themselves explain Chromium HTTP403 responses; direct Python HTTP is a separate transport.'},'conclusions':[{'finding':'No universal standalone-browser failure','evidence':['probes/gridics-chromium148-headless/receipt.json','probes/gridics-chrome155-headless/receipt.json'],'meaning':'Both ordinary engines reached the same expected public legal containers without prior cookies/operator initialization.'},{'finding':'Prior directHTTP403 is not universal public-source denial','evidence':['prior-evidence/gridics-direct-http.json','probes/gridics-chromium148-headless/receipt.json'],'meaning':'Same publisher source has retained directHTTP403 and successful ordinary standalone browser200; do not generalize transport-specific failures.'},{'finding':'CodePublishing requester-conditional challenge still blocks this distinct standard configuration','evidence':['prior-evidence/cp-chrome155-headless.json','probes/flagstaff-chromium148-headed/receipt.json'],'meaning':'InstalledChrome155 headless prior403 and bundledChromium148 headed fresh403 both rejected legal content. The contrast changes engine and mode together; it does not isolate cause or prove every normal browser/session is blocked.'},{'finding':'Family evidence shows normal headed/browser UI can close some gaps','evidence':['prior-evidence/municipal-headed-berkeley-ca.json','prior-evidence/municipal-headed-petaluma-ca.json','prior-evidence/municipal-headed-sonoma-ca.json','prior-evidence/municipal-headed-bellingham-wa.json','prior-evidence/municipal-headed-stable-bellingham-wa.json','prior-evidence/municipal-ui-download-berkeley-ca.json','prior-evidence/municipal-ui-download-everett-wa.json'],'meaning':'Four initial ordinary headed legal captures accepted expected nodes; later Bellingham429 stops that host. Berkeley/Everett normal UI initiated actual export downloads without operator actions; download-related page.goto errors are not equivalent to publisher403. These are agent-retained source receipts, not repeated diagnostics.'},{'finding':'HTTP200 alone is insufficient','evidence':['prior-evidence/municipal-headed-everett-wa.json'],'meaning':'Everett legal navigation initially200 but challenge/nonmatching identity was rejected; expected source identity or parsed downloaded payload remains necessary.'}], 'host_stop_policy':{'ledger':'probes/HOST-STOP.json','stopped_hosts':read(ROOT/'probes/HOST-STOP.json')['stopped_hosts'],'retry_after':'Record exact header when available; stop all later jobs on that requested hostname; no automatic retries even after Retry-After. Missing prior header values stay unknown.','repeated_experiment':'Same URL/engine/mode is refused across output directories sharing the ledger.','actual_scope':'Diagnostic sent zeroecode requests; only mocked429 exercised newly implemented stop behavior. Family actual429 receipts seed the stop ledger.'},'operator_assisted_initialization':{'needed_for_successful_controls':False,'persistent_profile_implemented':False,'user_cookie_profile_imported':False,'manual_challenge_initialization':'not attempted or validated; no challenge interaction, authentication or CAPTCHA solving performed','limits':'Immediate-denial negative probes do not establish permanent access policy or that eventual passive site behavior can never differ. Managed CUA success does not prove a portable clean-profile initialization path.'},'portable_dependencies':{'inventory_and_offline_tests':'Python standard library; actual offline testsPython3.12','live_probe':'Install pinned Playwright1.64.0 withPython>=3.10 and its matching official browser binary, or an installed branded Chrome channel. Older control1.60/Chromium148 was retained without changing sealed runtimes.','cross_platform_status':'Only macOS arm64 actual execution; Windows/Linux are vendor-documented provisioning paths, not tested here. Headed requires a GUI/display.','package_exclusions':['__pycache__/','.venv/','.browsers/','node_modules/','browser caches','profiles','storage-state/cookie exports'],'runtime_installs_in_this_folder':False},'primary_documentation':[{'url':'https://playwright.dev/python/docs/browsers','used_for':'matched browser binaries, channel/headless implementation differences and platform dependency provisioning'},{'url':'https://playwright.dev/python/docs/intro#system-requirements','used_for':'vendor platform support reference; installed package metadata governs precise Python release minimum'},{'url':'https://playwright.dev/python/docs/ci','used_for':'OS/CI browser dependencies and display provisioning'},{'url':'https://playwright.dev/python/docs/downloads','used_for':'normal UI download event/save handling before closing context'}],'prior_evidence':prior,'limitations':['No browser fingerprint/UA/proxy/TLS/credential workaround was applied; no cause-specific anti-bot conclusion can be established from this bounded sample.','Browser versions/modes are recorded per receipt; package/library/engine differences are not a complete factorial experiment.','No publisher totals, current legal version or corpus completeness is qualified by runtime diagnostics.','Prior summaries preserve source receipt hashes; family packages own legal/download parse/export acceptance and any later evidence updates.']}
 report['artifact_hashes']={str(p.relative_to(ROOT)):sha(p) for p in sorted(ROOT.rglob('*')) if p.is_file() and p.name!='RUNTIME-FINDINGS.json' and not any(x in {'__pycache__','.venv','.browsers','node_modules'} for x in p.relative_to(ROOT).parts)}
 (ROOT/'RUNTIME-FINDINGS.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'status':report['status'],'tests':report['tests'],'live_experiments':{k:{f:v[f] for f in ['http_status','engine','headed','browser','result']} for k,v in probes.items()},'artifact_hashes':len(report['artifact_hashes']),'source_hash':report['source']['current_script_sha256']},indent=2))
if __name__=='__main__':main()
